 internal static Dictionary<string,object?> User(int id,int relation,long now,bool compact=false)
 {
  if(!Known(id)||relation is <1 or >4)throw new InvalidDataException("Unknown local Bot support.");
  var legacy=Canonical(id)==CanonicalId;var n=id==CanonicalId?0:Array.IndexOf(SupportIds,id);var row=legacy?Data.RootElement[n]:PeerData.RootElement[id-2147000020];var card=row.GetProperty("card");
  var value=new Dictionary<string,object?>{["user_id"]=id,["my_game_id"]=PublicId(id,compact),["status"]=0,
   ["name"]=id==CanonicalId?"LOCAL BOT":legacy?"LOCAL BOT / "+row.GetProperty("name").GetString():"LOCAL BOT "+(id-2147000018)+" / "+row.GetProperty("name").GetString(),
   ["message"]="ローカル検証用サポート。所持品には追加されません。",["rank"]=100,["title_id1"]=0,["title_id2"]=0,
   ["last_login_at"]=DateTimeOffset.FromUnixTimeSeconds(now).ToOffset(TimeSpan.FromHours(9)).ToString("yyyy-MM-dd HH:mm:ss",CultureInfo.InvariantCulture),
   ["support_card_id"]=row.GetProperty("card_id").GetInt32(),["support_card_lv"]=card.GetProperty("lv").GetInt32(),
   ["support_card_awakening_count"]=card.GetProperty("awakening_count").GetInt32(),["support_card_kill_ability_lv"]=card.GetProperty("kill_ability_lv").GetInt32(),
   ["support_card_main_skill_lv"]=card.GetProperty("main_skill_lv").GetInt32(),["support_card_kill_zone_skill_lv"]=card.GetProperty("kill_zone_skill_lv").GetInt32(),
   ["support_card_mastery_lv"]=card.GetProperty("mastery_lv").GetInt32(),["support_card_skin_id"]=card.GetProperty("card_skin_id").GetInt32(),["friend_type"]=relation};
  for(var i=0;i<3;i++)
  {
   var e=row.GetProperty("equips")[i];var key="support_equip_slot_"+(i+1)+"_";
   value[key+"id"]=e.GetProperty("equip_id").GetInt32();value[key+"lv"]=e.GetProperty("lv").GetInt32();value[key+"over_limit_count"]=e.GetProperty("over_limit_count").GetInt32();
   value[key+"free_property_ids"]=string.Join(',',e.GetProperty("free_property_ids").EnumerateArray().Select(v=>v.GetInt32()));
  }
  return value;
 }
